export interface InvoiceMetadata {
  brand: string;
  exportDate: string;
  totalQty: number;
  containerInfo: string;
  invoiceTitle: string;
}

export interface ProductionLineItem {
  poNo: string;
  woNo: string;
  partNo: string;
  customer: string;
  itemType: string;
  size: string;
  color: string;
  poQty: number;
  stockIn: number;
  remaining: number;
  usedForShipment: number;
  readyForShipment: number;
  reworkQty: number;
  finishedGoodsInventory: number;
  invoiceQtys: number[]; // From columns Q onwards
}

export interface DashboardData {
  invoices: InvoiceMetadata[];
  items: ProductionLineItem[];
  summary: {
    totalPoQty: number;
    totalStockIn: number;
    totalRemaining: number;
    totalRework: number;
    totalInventory: number;
  };
}

import { DashboardData, InvoiceMetadata, ProductionLineItem } from '../types';

const SHEET_URL = 'https://docs.google.com/spreadsheets/d/1XoV7020NTZk1kzqn3F2ks3gOVFJ5arr5NVgUdewWPNQ/export?format=csv&gid=1100244896';

function parseCSV(csvText: string): string[][] {
  const rows = [];
  let currentRow = [];
  let currentField = '';
  let inQuotes = false;

  for (let i = 0; i < csvText.length; i++) {
    const char = csvText[i];
    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      currentRow.push(currentField.trim());
      currentField = '';
    } else if ((char === '\r' || char === '\n') && !inQuotes) {
      if (currentField || currentRow.length > 0) {
        currentRow.push(currentField.trim());
        rows.push(currentRow);
        currentRow = [];
        currentField = '';
      }
      if (char === '\r' && csvText[i + 1] === '\n') i++;
    } else {
      currentField += char;
    }
  }
  if (currentField || currentRow.length > 0) {
    currentRow.push(currentField.trim());
    rows.push(currentRow);
  }
  return rows;
}

export async function fetchDashboardData(): Promise<DashboardData> {
  const response = await fetch(SHEET_URL);
  if (!response.ok) throw new Error('Failed to fetch spreadsheet data');
  const csvText = await response.text();
  const rows = parseCSV(csvText);

  // Parse Invoices Metadata (Rows 1-5, starting from Column Q (index 16))
  const invoices: InvoiceMetadata[] = [];
  if (rows.length >= 5) {
    const startCol = 16; // Column Q
    for (let col = startCol; col < rows[0].length; col++) {
      if (!rows[0][col]) break;
      invoices.push({
        brand: rows[0][col] || '',
        exportDate: rows[1][col] || '',
        totalQty: parseInt(rows[2][col]) || 0,
        containerInfo: rows[3][col] || '',
        invoiceTitle: rows[4][col] || '',
      });
    }
  }

  // Parse Line Items (Row 6 onwards, index 5)
  const items: ProductionLineItem[] = [];
  for (let i = 5; i < rows.length; i++) {
    const r = rows[i];
    if (!r || !r[0]) continue; // Skip empty rows

    const invoiceQtys: number[] = [];
    for (let col = 16; col < r.length; col++) {
      invoiceQtys.push(parseInt(r[col]) || 0);
    }

    items.push({
      poNo: r[0] || '',
      woNo: r[1] || '',
      partNo: r[2] || '',
      customer: r[3] || '',
      itemType: r[4] || '',
      size: r[5] || '',
      color: r[7] || '', // Column H is index 7
      poQty: parseInt(r[8]) || 0, // I
      stockIn: parseInt(r[9]) || 0, // J
      remaining: parseInt(r[10]) || 0, // K
      usedForShipment: parseInt(r[11]) || 0, // L
      readyForShipment: parseInt(r[12]) || 0, // M
      reworkQty: parseInt(r[13]) || 0, // N
      finishedGoodsInventory: parseInt(r[14]) || 0, // O
      invoiceQtys,
    });
  }

  // Calculate Summary
  const summary = items.reduce(
    (acc, item) => ({
      totalPoQty: acc.totalPoQty + item.poQty,
      totalStockIn: acc.totalStockIn + item.stockIn,
      totalRemaining: acc.totalRemaining + item.remaining,
      totalRework: acc.totalRework + item.reworkQty,
      totalInventory: acc.totalInventory + item.finishedGoodsInventory,
    }),
    { totalPoQty: 0, totalStockIn: 0, totalRemaining: 0, totalRework: 0, totalInventory: 0 }
  );

  return { invoices, items, summary };
}

import { GoogleGenAI } from "@google/genai";
import { DashboardData } from "../types";

export async function getAiInsights(data: DashboardData): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const summaryContext = `
    Production Summary:
    - Total PO Qty: ${data.summary.totalPoQty}
    - Total Stock In: ${data.summary.totalStockIn}
    - Total Remaining: ${data.summary.totalRemaining}
    - Total Rework: ${data.summary.totalRework}
    - Current Inventory: ${data.summary.totalInventory}

    Top Items by Inventory:
    ${data.items.slice(0, 5).map(i => `- ${i.partNo} (${i.customer}): ${i.finishedGoodsInventory}`).join('\n')}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze this production data and provide 3-4 actionable bullet-point insights for management. Focus on rework issues, inventory levels, and production bottlenecks. Keep it professional and concise. \n\n ${summaryContext}`,
    });

    return response.text || "Unable to generate insights at this time.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Error connecting to AI advisor. Please try again later.";
  }
}

import React, { useEffect, useState } from 'react';
import { fetchDashboardData } from './services/googleSheetService';
import { getAiInsights } from './services/geminiService';
import { DashboardData } from './types';
import Dashboard from './components/Dashboard';

const App: React.FC = () => {
  const [data, setData] = useState<DashboardData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [insights, setInsights] = useState<string>("");
  const [isGeneratingInsights, setIsGeneratingInsights] = useState(false);

  useEffect(() => {
    const loadData = async () => {
      try {
        setLoading(true);
        const fetchedData = await fetchDashboardData();
        setData(fetchedData);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, []);

  const handleGenerateInsights = async () => {
    if (!data) return;
    setIsGeneratingInsights(true);
    try {
      const result = await getAiInsights(data);
      setInsights(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsGeneratingInsights(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
        <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-slate-600 font-medium animate-pulse">Loading Production Data...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4">
        <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md w-full border border-red-100 text-center">
          <div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4 text-2xl">
            <i className="fas fa-exclamation-triangle"></i>
          </div>
          <h2 className="text-xl font-bold text-slate-800 mb-2">Sync Failed</h2>
          <p className="text-slate-600 mb-6">{error}</p>
          <button 
            onClick={() => window.location.reload()}
            className="w-full bg-slate-800 text-white py-3 rounded-xl font-semibold hover:bg-slate-900 transition-colors"
          >
            Retry Connection
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50">
      {data && (
        <Dashboard 
          data={data} 
          insights={insights} 
          isGeneratingInsights={isGeneratingInsights}
          onGenerateInsights={handleGenerateInsights}
        />
      )}
    </div>
  );
};

export default App;

