              <i className="fas fa-brain text-8xl"></i>
            </div>
            <h3 className="text-slate-400 font-bold uppercase text-xs tracking-widest mb-4 flex items-center gap-2">
              <i className="fas fa-sparkles text-blue-400"></i> {t.aiSummary}
