                                style={{ width: `${percent}%` }}
                              ></div>
                            </div>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
              {filteredItems.length === 0 && (
                <div className="p-16 text-center text-slate-400">
                  <div className="text-4xl mb-3"><i className="fas fa-search"></i></div>
                  <p className="italic">No records found for "{searchTerm}"</p>
                </div>
