                  <p key={i} className="flex gap-2">
                    <span className="text-blue-500">•</span>
                    <span>{line.replace(/^[*-]\s*/, '')}</span>
                  </p>
                ))}
              </div>
            ) : (
              <div className="py-8 text-center text-slate-500">
                <i className="fas fa-chart-line text-4xl mb-4 opacity-50 block"></i>
                <p className="text-sm">{t.clickInsights}</p>
              </div>
            )}
          </div>

          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
            <h3 className="text-slate-500 font-bold uppercase text-xs tracking-widest mb-6">{t.topCustomers}</h3>
            <div className="space-y-4">
              {topCustomers.length > 0 ? topCustomers.map(([name, val], idx) => {
                const percentage = topCustomers[0][1] > 0 ? (val / topCustomers[0][1]) * 100 : 0;
                return (
                  <div key={name} className="space-y-1">
                    <div className="flex justify-between text-xs font-bold text-slate-600">
                      <span className="truncate max-w-[140px]">{name}</span>
                      <span>{val.toLocaleString()}</span>
                    </div>
                    <div className="h-2 w-full bg-slate-50 rounded-full overflow-hidden shadow-inner">
                      <div 
                        className={`h-full rounded-full transition-all duration-1000`} 
                        style={{ width: `${percentage}%`, backgroundColor: ['#2563eb', '#3b82f6', '#60a5fa', '#93c5fd', '#bfdbfe'][idx % 5] }}
                      ></div>
                    </div>
                  </div>
                );
              }) : <div className="text-center py-4 text-slate-400 text-xs italic">{t.noData}</div>}
            </div>
          </div>

