        dates[inv.exportDate][inv.brand] = (dates[inv.exportDate][inv.brand] || 0) + inv.totalQty;
      }
    });
    return Object.entries(dates).sort((a, b) => {
      const dA = parseSpreadsheetDate(a[0])?.getTime() || 0;
