                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center font-bold text-emerald-600">{exportValue.toLocaleString()}</td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex flex-col items-center gap-1">
                        <span className="text-[10px] font-black text-emerald-600">{Math.round(shipRatio)}%</span>
                        <div className="w-20 bg-slate-100 h-1 rounded-full overflow-hidden">
                          <div className="h-full bg-emerald-500" style={{ width: `${Math.min(shipRatio, 100)}%` }}></div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <span className="bg-indigo-50 text-indigo-700 px-3 py-1 rounded-lg text-xs font-black border border-indigo-100">{metrics.inventory.toLocaleString()}</span>
                    </td>
                    <td className="px-6 py-4 text-center">
                      {metrics.rework > 0 ? (
                        <span className="bg-rose-50 text-rose-700 px-3 py-1 rounded-lg text-xs font-black border border-rose-100">{metrics.rework.toLocaleString()}</span>
