  // Derive available months strictly for 2025 and 2026
  const availableMonths = useMemo(() => {
    const months = new Set<string>();
    data.invoices.forEach(inv => {
      const date = parseSpreadsheetDate(inv.exportDate);
      if (date) {
        const year = date.getFullYear();
        // Eliminate 2001 or other years - strictly 2025 and 2026
        if (year === 2025 || year === 2026) {
          const monthKey = `${year}-${String(date.getMonth() + 1).padStart(2, '0')}`;
          months.add(monthKey);
        }
      }
    });
    return Array.from(months).sort().reverse(); 
  }, [data.invoices]);

  // Color map for brands
  const brandColors = useMemo(() => {
    const palette = ['#6366f1', '#10b981', '#f59e0b', '#ef4444', '#3b82f6', '#8b5cf6', '#ec4899', '#06b6d4', '#14b8a6', '#f97316'];
    const map: Record<string, string> = {};
    let idx = 0;
    data.invoices.forEach(inv => {
      if (inv.brand && !map[inv.brand]) {
        map[inv.brand] = palette[idx % palette.length];
        idx++;
      }
    });
    data.items.forEach(item => {
        if (item.customer && !map[item.customer]) {
          map[item.customer] = palette[idx % palette.length];
          idx++;
        }
    });
    return map;
  }, [data.invoices, data.items]);

  // Filter invoices based on selected month
  const filteredInvoices = useMemo(() => {
    if (selectedMonth === 'all') return data.invoices;
    return data.invoices.filter(inv => {
      const date = parseSpreadsheetDate(inv.exportDate);
      if (!date) return false;
      const monthKey = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
      return monthKey === selectedMonth;
    });
  }, [data.invoices, selectedMonth]);

  // Total export volume for the selected period
  const periodTotalExport = useMemo(() => {
    return filteredInvoices.reduce((acc, inv) => acc + inv.totalQty, 0);
  }, [filteredInvoices]);

  // Comprehensive brand aggregation for the "Report"
  const fullBrandReport = useMemo(() => {
    const report: Record<string, {
      po: number;
      stockIn: number;
      rework: number;
      inventory: number;
      shippedTotal: number;
      shippedPeriod: number;
    }> = {};

    // Map which indices in the original invoices array match the period filter
    const invoiceIndicesInPeriod = data.invoices.map((inv, idx) => {
      const d = parseSpreadsheetDate(inv.exportDate);
      if (!d) return false;
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      return selectedMonth === 'all' || key === selectedMonth;
    });

    data.items.forEach(i => {
      const brand = i.customer || 'Unassigned';
      if (!report[brand]) {
        report[brand] = { po: 0, stockIn: 0, rework: 0, inventory: 0, shippedTotal: 0, shippedPeriod: 0 };
      }
      report[brand].po += i.poQty;
      report[brand].stockIn += i.stockIn;
      report[brand].rework += i.reworkQty;
      report[brand].inventory += i.finishedGoodsInventory;
      report[brand].shippedTotal += i.usedForShipment;

      // Calculate period-specific shipment
      i.invoiceQtys.forEach((qty, idx) => {
        if (invoiceIndicesInPeriod[idx]) {
          report[brand].shippedPeriod += qty;
        }
      });
    });

    return Object.entries(report).sort((a, b) => b[1].po - a[1].po);
  }, [data.items, data.invoices, selectedMonth]);

  const exportByBrand = useMemo(() => {
    const brands: Record<string, number> = {};
